// The time zones of the tz database (IANA) with their current rules as POSIX TZ strings,
// without hardware dependencies (tested on the PC). The data, src/tz_table_data.inc (about
// 11 KB, in flash), is generated by tools/gen_tz_table.py: the rule of a zone is the footer
// of its TZif file (RFC 8536, section 3.3).
#pragma once

namespace tz_table {

// Version of the tz database the table was generated from, e.g. "2026e".
const char *tzdataVersion();

// Looks a zone up by name, ignoring case; aliases such as "Poland" count as names. On success
// *tableName is the name as the table spells it and *rule its POSIX TZ rule (both constant
// strings in flash). An unknown name returns false and leaves both unchanged.
bool find(const char *name, const char **tableName, const char **rule);

} // namespace tz_table
